<?php
require_once __DIR__ . '/../helpers/response.php';
class SearchHistoryController {public function __construct(private SearchHistoryService $s){}public function save(){jsonResponse($this->s->save((string)queryParam('vehicleNumber',''),(string)queryParam('userEmail',''),(string)queryParam('userName',''),(string)queryParam('agencyId','')));}public function list(){jsonResponse($this->s->list((string)queryParam('agencyId','')));}public function all(){jsonResponse($this->s->all());}public function search(){jsonResponse($this->s->search((string)queryParam('agencyId',''),(string)queryParam('vehicleNumber','')));}public function user(){jsonResponse($this->s->byUser((string)queryParam('agencyId',''),(string)queryParam('userName','')));}public function date(){jsonResponse($this->s->byDate((string)queryParam('agencyId',''),(string)queryParam('date','')));}public function sort(){jsonResponse($this->s->sort((string)queryParam('agencyId',''),(string)queryParam('order','')));}}
